-- Felwood: creature abilities
-- Most of the zone's creatures (the Jadefire and Deadwood, the Shadow Council, the Irontree, the corrupted beasts and oozes) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '7092,7093,7097,7099,7100,7104,7105,7106,7109,7110,7112,7113,7114,7115,7118,7120,7125,7126,7136,7137,7139,7149,8956,8959,8960,9454,9462,9516,9517,9860,9861,9862,9877,10916,14339,14340,14342,14343,14344,14345,26043,47398,47439,47601,47675,47679,47747,47795,47800,48038,48154,48259,48311,48315,48331,48344,48352,48453,48455,48456,48556';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '7135,11552,51610,51845';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
